import{_ as i,o as r,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson Verification on AArch64 - Rixin Luo, Huawei","description":"","frontmatter":{"title":"Ceph Crimson Verification on AArch64 - Rixin Luo, Huawei","date":"2023-05-18T00:00:00.000Z","updated":"2023-05-19T00:00:00.000Z","tags":["Ceph","Crimson","AArch64","ARM","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_Verification_on_AArch64_-_Rixin_Luo_Huawei.md","filePath":"posts/2023/Ceph_Crimson_Verification_on_AArch64_-_Rixin_Luo_Huawei.md","lastUpdated":1780459816000}'),l={name:"posts/2023/Ceph_Crimson_Verification_on_AArch64_-_Rixin_Luo_Huawei.md"};function t(n,a,s,h,u,d){return r(),o("div",null,[...a[0]||(a[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-crimson验证在arc-34上的部署与优化" tabindex="-1">会议主题：Crimson验证在Arc 34上的部署与优化 <a class="header-anchor" href="#会议主题-crimson验证在arc-34上的部署与优化" aria-label="Permalink to &quot;会议主题：Crimson验证在Arc 34上的部署与优化&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主持人-lindsay" tabindex="-1">主持人：Lindsay <a class="header-anchor" href="#主持人-lindsay" aria-label="Permalink to &quot;主持人：Lindsay&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><ol><li><p><strong>部署与优化</strong></p><ul><li><strong>部署方法</strong>：通过yum文件添加代码，支持在ARM版本上构建Crimson镜像，并使用Benchmark工具如rados bench和fio进行性能测试。</li><li><strong>优化进展</strong>：PRS self-adium部分已由Adam King审核，希望有人能帮助审查并合并。</li></ul></li><li><p><strong>内存泄漏与浪费</strong></p><ul><li><strong>问题描述</strong>：在内存存储中，大量小写操作会导致缓冲区列表包含许多无效数据，无法重用保留的内存页，可能导致内存不足。</li><li><strong>解决计划</strong>：将问题贡献给社区，并继续优化。</li></ul></li><li><p><strong>性能优化</strong></p><ul><li><strong>瓶颈分析</strong>：发现原子操作在内存端口模块中占用近35%的overhead，建议禁用lse指令以减少争用。</li><li><strong>测试结果</strong>：禁用lse后，使用2MB页面大小，对于小包和大包分别获得50%和8%的性能提升。</li></ul></li><li><p><strong>多节点集群测试</strong></p><ul><li><strong>测试环境</strong>：使用三台ARM服务器构建测试场景，使用36个OSD和三副本。</li><li><strong>测试结果</strong>：系统在单次测试中表现良好，但与经典BlueStore相比，性能仍有差距，正在进行优化。</li></ul></li><li><p><strong>社区贡献与未来计划</strong></p><ul><li><strong>贡献内容</strong>：将优化代码和协议贡献给社区，包括内存池和缓冲区列表的优化。</li><li><strong>未来工作</strong>：继续优化Ceph存储系统，特别是C-Store部分，解决读写放大问题，并进行更多测试案例和CI集成。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续优化Crimson的部署和性能，特别是内存管理和原子操作的优化。</li><li>将优化成果和协议贡献给Ceph社区。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成PRS self-adium部分的合并。</li><li>继续进行多节点集群的性能测试和优化。</li><li>解决内存泄漏和浪费问题，并贡献给社区。</li><li>优化C-Store的读写放大问题，并进行更多测试。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在提问环节后圆满结束，Lindsay感谢大家的参与和贡献。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>如有进一步问题或需要更多技术细节，请联系Jason Johnson或发送邮件至[相关邮箱]。</li></ul><p>[会议纪要结束]</p>',17)])])}const m=i(l,[["render",t]]);export{_ as __pageData,m as default};
